                        onDragEnd={() => setDragPhotoId(null)}
                        className={`relative ${dragPhotoId === p.id ? "opacity-40" : ""}`}
                        title="Click to view · Drag to reorder"
                      >
                        <button
                          type="button"
                          onClick={() => setLightbox({ item: lightbox.item, index: i })}
